appsmith.onReady(function () {
  var validViews = ['overview', 'conversation', 'sources', 'actors'];
  var viewMeta = {
    overview: {
      title: 'Panorama general',
      subtitle: 'Una visión general de la conversación monitoreada.'
    },
    conversation: {
      title: 'Conversación',
      subtitle: 'Explora los temas, publicaciones y señales presentes en la conversación.'
    },
    sources: {
      title: 'Fuentes',
      subtitle: 'Revisa dónde se está produciendo la conversación y qué fuentes tienen mayor presencia.'
    },
    actors: {
      title: 'Actores',
      subtitle: 'Identifica las personas, cuentas y entidades con mayor relevancia en la conversación.'
    }
  };
  function getModel(modelOverride) {
    return modelOverride || appsmith.model || {};
  }
  function normalizeView(value) {
    var view = String(value || '').trim().toLowerCase();
    if (validViews.indexOf(view) !== -1) {
      return view;
    }
    return 'overview';
  }
  function setActiveViewVisual(view) {
    var navItems = document.querySelectorAll('.summary-nav-item');
    navItems.forEach(function (item) {
      var isActive = item.getAttribute('data-view') === view;
      item.classList.toggle('active', isActive);
      item.setAttribute('aria-current', isActive ? 'page' : 'false');
    });
    var panels = document.querySelectorAll('[data-view-panel]');
    panels.forEach(function (panel) {
      var isActive = panel.getAttribute('data-view-panel') === view;
      panel.classList.toggle('active', isActive);
    });
    var meta = viewMeta[view] || viewMeta.overview;
    var title = document.getElementById('summaryTitle');
    var subtitle = document.getElementById('summarySubtitle');
    if (title) {
      title.textContent = meta.title;
    }
    if (subtitle) {
      subtitle.textContent = meta.subtitle;
    }
  }
  function syncQueryContext(modelOverride) {
    var model = getModel(modelOverride);
    var queryName = String(model.activeQueryName || '').trim();
    var queryId = String(model.activeQueryId || '').trim();
    var nameElement = document.getElementById('summaryQueryName');
    var dot = document.querySelector('.query-context-dot');
    if (nameElement) {
      nameElement.textContent = queryName || 'Sin consulta seleccionada';
    }
    if (dot) {
      dot.style.opacity = queryId ? '1' : '0.3';
    }
  }
  function syncPeriod(modelOverride) {
    var model = getModel(modelOverride);
    var period = String(model.period || '30d');
    var select = document.getElementById('summaryPeriod');
    if (select && select.value !== period) {
      select.value = period;
    }
  }
  function syncWidget(modelOverride) {
    var model = getModel(modelOverride);
    var view = normalizeView(model.activeView);
    setActiveViewVisual(view);
    syncQueryContext(model);
    syncPeriod(model);
  }
  async function changeView(view) {
    var nextView = normalizeView(view);
    setActiveViewVisual(nextView);
    try {
      await appsmith.updateModel({
        activeView: nextView
      });
    } catch (error) {
      console.error('No fue posible cambiar la vista de Resumen:', error);
      syncWidget();
    }
  }
  async function changePeriod(period) {
    var value = String(period || '30d');
    try {
      await appsmith.updateModel({
        period: value
      });
    } catch (error) {
      console.error('No fue posible cambiar el periodo:', error);
      syncPeriod();
    }
  }
  function bindNavigation() {
    var items = document.querySelectorAll('.summary-nav-item');
    items.forEach(function (item) {
      item.addEventListener('click', function () {
        changeView(item.getAttribute('data-view'));
      });
    });
  }
  function bindPeriod() {
    var select = document.getElementById('summaryPeriod');
    if (!select) {
      return;
    }
    select.addEventListener('change', function () {
      changePeriod(select.value);
    });
  }
  bindNavigation();
  bindPeriod();
  syncWidget();
  if (typeof appsmith.onModelChange === 'function') {
    appsmith.onModelChange(function (newModel) {
      syncWidget(newModel);
    });
  }
});

